function ProfileScreen({ userName, setUserName, avatarId, setAvatarId, onBack }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(userName);

  const save = () => {
    const trimmed = draft.trim();
    if (trimmed) setUserName(trimmed);
    setEditing(false);
  };

  return (
    <>
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 24px 0" }}>
        <button onClick={onBack} style={{ width: 34, height: 34, borderRadius: "50%", border: "none", background: C[200], display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
          <ChevronLeft size={18} color={C[950]} />
        </button>
        <div>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: 1.5, color: C[700] }}>ACCOUNT</div>
          <div style={{ fontSize: 19, fontWeight: 800, color: C[950] }}>Profile</div>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "22px 24px 120px" }}>
        {/* Avatar + name card */}
        <div style={{
          background: "linear-gradient(160deg,#FFD544 0%,#FEBE11 60%,#CD7D01 100%)",
          borderRadius: 26, padding: "26px 20px", display: "flex", flexDirection: "column",
          alignItems: "center", gap: 14, marginBottom: 24,
        }}>
          <div style={{
            width: 74, height: 74, borderRadius: "50%", background: "#000000",
            color: "#FEBE11", display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 24, fontWeight: 800, border: "3px solid #FEFBE8", overflow: "hidden",
          }}>
            {avatarId
              ? <img src={AVATARS.find((a) => a.id === avatarId)?.img} alt="Your avatar" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              : initialsOf(userName)}
          </div>

          {!editing ? (
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ fontSize: 18, fontWeight: 800, color: "#000000" }}>{userName}</span>
              <button
                onClick={() => { setDraft(userName); setEditing(true); }}
                style={{ border: "none", background: "rgba(0,0,0,0.12)", borderRadius: "50%", width: 26, height: 26, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}
              >
                <Pencil size={13} color="#000000" />
              </button>
            </div>
          ) : (
            <div style={{ display: "flex", alignItems: "center", gap: 8, width: "100%" }}>
              <input
                autoFocus
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter") save(); }}
                placeholder="Your name"
                style={{
                  flex: 1, fontSize: 15, fontWeight: 700, color: "#000000",
                  background: "#FEFBE8", border: "none", borderRadius: 12,
                  padding: "9px 12px", outline: "none",
                }}
              />
              <button
                onClick={save}
                style={{ border: "none", background: "#000000", borderRadius: "50%", width: 32, height: 32, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0 }}
              >
                <Check size={16} color="#FEBE11" />
              </button>
            </div>
          )}
          <span style={{ fontSize: 11.5, fontWeight: 600, color: "rgba(0,0,0,0.55)" }}>
            ACES member
          </span>
        </div>

        {/* Avatar picker */}
        <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: C[700], marginBottom: 10, textTransform: "uppercase" }}>
          Choose your avatar
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 10, marginBottom: 24 }}>
          {AVATARS.map((a) => (
            <button
              key={a.id}
              onClick={() => setAvatarId(avatarId === a.id ? null : a.id)}
              style={{
                display: "flex", flexDirection: "column", alignItems: "center", gap: 6,
                background: C[100], borderRadius: 18, padding: "10px 6px", cursor: "pointer",
                border: avatarId === a.id ? `3px solid ${C[950]}` : `3px solid transparent`,
              }}
            >
              <div style={{ width: 48, height: 48, borderRadius: "50%", overflow: "hidden", border: `1px solid ${C[300]}`, background: "#FFFFFF" }}>
                <img src={a.img} alt={a.label} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              </div>
              <span style={{ fontSize: 10.5, fontWeight: 700, color: C[950] }}>{a.label}</span>
            </button>
          ))}
        </div>

        {/* About this app */}
        <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: C[700], marginBottom: 10, textTransform: "uppercase" }}>
          About this app
        </div>
        <div style={{ background: C[100], borderRadius: 20, border: `1px solid ${C[200]}`, padding: 18, marginBottom: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
            <div style={{ width: 40, height: 40, borderRadius: 12, overflow: "hidden", flexShrink: 0, border: `1px solid ${C[300]}` }}>
              <img src={ACES_LOGO_IMG} alt="ACES logo" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
            </div>
            <div>
              <div style={{ fontSize: 15, fontWeight: 800, color: C[950] }}>NaviGate</div>
              <div style={{ fontSize: 11.5, fontWeight: 600, color: C[700] }}>Version 1.0.0</div>
            </div>
          </div>
          <p style={{ fontSize: 13, lineHeight: 1.6, color: C[950], margin: 0 }}>
            NaviGate is a pocket reference for Computer Engineering students - components, logic
            gates, unit conversions, and build notes, all in one place for quick
            lookups between classes and lab sessions.
          </p>
        </div>

        <div style={{ background: C[100], borderRadius: 20, border: `1px solid ${C[200]}`, padding: 18, display: "flex", gap: 12, alignItems: "flex-start", marginBottom: 24 }}>
          <Info size={18} color={C[700]} style={{ marginTop: 2, flexShrink: 0 }} />
          <p style={{ fontSize: 12.5, lineHeight: 1.6, color: C[800], margin: 0 }}>
            Built for and by the <strong>Association of Computer Engineering Students
            (ACES)</strong>, to help members review the basics anytime, anywhere.
          </p>
        </div>

        {/* Developer */}
        <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: C[700], marginBottom: 10, textTransform: "uppercase" }}>
          Developer
        </div>
        <div style={{ background: C[100], borderRadius: 20, border: `1px solid ${C[200]}`, padding: 18, display: "flex", alignItems: "center", gap: 14 }}>
          <div style={{ width: 52, height: 52, borderRadius: "50%", overflow: "hidden", flexShrink: 0, border: `2px solid ${C[400]}`, background: "#FFFFFF" }}>
            <img src={CHICKY_AVATAR_IMG} alt="Developer avatar" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          </div>
          <div>
            <div style={{ fontSize: 15, fontWeight: 800, color: C[950] }}>Abelong Mariel</div>
            <div style={{ fontSize: 11.5, fontWeight: 600, color: C[700] }}>Developer</div>
          </div>
        </div>
      </div>
    </>
  );
}


