/* ---- the 6 sockets of this 5V/7805 supply. Each socket accepts any chip
   whose `slot` matches it (same footprint) - but only one chip per socket
   is actually the *right* value. Wrong value still clicks into place;
   it just won't survive being powered on. ---- */
const BUILD_CHIP_POOL = [
  { uid: "T1-ok", slot: "T1", glyph: "transformer", name: "T1 - 0-9V transformer", spec: "230V → 9V AC, 2A", correct: true },
  { uid: "T1-bad", slot: "T1", glyph: "transformer", name: "0-15V transformer", spec: "230V → 15V AC, 2A", correct: false },
  { uid: "D1-ok", slot: "D1", glyph: "bridge", name: "D1 - Bridge rectifier", spec: "2A full-wave", correct: true },
  { uid: "C1-ok", slot: "C1", glyph: "capE", name: "C1 - Filter cap", spec: "470µF / 50V", correct: true },
  { uid: "C1-bad", slot: "C1", glyph: "capE", name: "Small filter cap", spec: "100µF / 16V", correct: false },
  { uid: "IC1-ok", slot: "IC1", glyph: "ic", name: "IC1 - 7805", spec: "5V linear reg.", correct: true },
  { uid: "IC1-bad", slot: "IC1", glyph: "ic", name: "7812 regulator", spec: "12V linear reg.", correct: false },
  { uid: "C2-ok", slot: "C2", glyph: "capC", name: "C2 - Ceramic", spec: "0.01µF", correct: true },
  { uid: "C3-ok", slot: "C3", glyph: "capC", name: "C3 - Ceramic", spec: "0.01µF", correct: true },
  { uid: "RX1", slot: "R", glyph: "resistor", name: "220Ω resistor", spec: "1/4W", correct: false },
  { uid: "RX2", slot: "R", glyph: "resistor", name: "10kΩ resistor", spec: "1/4W", correct: false },
  { uid: "LX1", slot: "L", glyph: "inductor", name: "100µH inductor", spec: "choke coil", correct: false },
  { uid: "LX2", slot: "L", glyph: "inductor", name: "1mH inductor", spec: "choke coil", correct: false },
];
const BUILD_SLOT_IDS = ["T1", "D1", "C1", "IC1", "C2", "C3"];
const BUILD_SLOT_KIND = { T1: "inline", D1: "inline", C1: "shunt", IC1: "inline", C2: "shunt", C3: "shunt" };
// shuffled tray order, correct + decoy chips mixed together - any chip can be dropped on any block
const BUILD_TRAY_ORDER = ["IC1-ok", "C1-bad", "D1-ok", "T1-bad", "RX1", "C3-ok", "T1-ok", "LX1", "C2-ok", "IC1-bad", "RX2", "C1-ok", "LX2"];

/* ---- fixed positions on the schematic (viewBox 0 0 VBW VBH) ---- */
const BUILD_VBW = 410, BUILD_VBH = 210;
const BUILD_YTOP = 62, BUILD_YBOT = 140;
const BUILD_SLOT_X = { T1: 60, D1: 128, C1: 168, C2: 198, IC1: 238, C3: 278 };
const BUILD_MAINS_X = 16, BUILD_OUT_X = 306, BUILD_BULB_X = 372;

/* ---- 5V bulb load: lights when everything upstream is correct,
   pops when it isn't. ---- */
function BuildBulb({ x, cy, state }) {
  const glow = state === "lit" ? "drop-shadow(0 0 12px rgba(255,214,90,0.9))" : "none";
  return (
    <g transform={`translate(${x},${cy})`}>
      {/* screw base */}
      <rect x="-6" y="14" width="12" height="8" fill="none" stroke={C[950]} strokeWidth="1.6" />
      <line x1="-6" y1="17" x2="6" y2="17" stroke={C[950]} strokeWidth="1" />
      <line x1="-6" y1="20" x2="6" y2="20" stroke={C[950]} strokeWidth="1" />

      {state === "exploded" ? (
        <>
          {/* scorch */}
          <ellipse cx="0" cy="4" rx="13" ry="10" fill="#2a1c10" opacity="0.35" />
          {/* jagged glass remnants instead of a full bulb */}
          <path d="M-13,2 L-6,-10 L-2,0 L4,-13 L8,-2 L13,3" fill="none" stroke={C[950]} strokeWidth="1.8" strokeLinejoin="round" />
          {/* burst spikes */}
          {[-40, -10, 20, 55, 100, 140, 190, 230].map((deg, i) => {
            const rad = (deg * Math.PI) / 180;
            return (
              <line key={i} x1={Math.cos(rad) * 10} y1={Math.sin(rad) * 10 - 6} x2={Math.cos(rad) * 22} y2={Math.sin(rad) * 22 - 6}
                stroke={BUILD_RED} strokeWidth="2" strokeLinecap="round" />
            );
          })}
        </>
      ) : (
        <>
          <circle cx="0" cy="-2" r="15" fill={state === "lit" ? "#FFE79A" : "none"} stroke={C[950]} strokeWidth="1.8" style={{ filter: glow, transition: "all .2s" }} />
          <path d="M-6,4 L-2,-8 L2,-3 L6,4" fill="none" stroke={state === "lit" ? "#B8720A" : C[950]} strokeWidth="1.6" strokeLinejoin="round" />
        </>
      )}
    </g>
  );
}

function SupplySchematic({ placed, wrongSlots, tested, passing }) {
  const chipAt = (id) => BUILD_CHIP_POOL.find((c) => c.uid === placed[id]);
  const railColor = tested ? (passing ? C[400] : BUILD_WIRE) : BUILD_WIRE;
  const wireW = 2;

  const seg = (x1, x2, y = BUILD_YTOP) => (
    <line x1={x1} y1={y} x2={x2} y2={y} stroke={railColor} strokeWidth={wireW} />
  );
  const inlineGap = 22; // half-width of inline slot box
  const shuntGap = 20; // half-height of shunt slot box, box sits mid-rail
  const midY = BUILD_YTOP + (BUILD_YBOT - BUILD_YTOP) / 2;
  const bulbState = !tested ? "idle" : passing ? "lit" : "exploded";

  return (
    <svg viewBox={`0 0 ${BUILD_VBW} ${BUILD_VBH}`} width="100%" height="auto" style={{ display: "block" }}>
      {/* mains stub, isolated, primary side only */}
      <circle cx={BUILD_MAINS_X} cy={BUILD_YTOP} r="3" fill="none" stroke={BUILD_WIRE} strokeWidth="1.6" />
      <circle cx={BUILD_MAINS_X} cy={BUILD_YTOP + 24} r="3" fill="none" stroke={BUILD_WIRE} strokeWidth="1.6" />
      <line x1={BUILD_MAINS_X} y1={BUILD_YTOP} x2={BUILD_SLOT_X.T1 - inlineGap} y2={BUILD_YTOP} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_MAINS_X} y1={BUILD_YTOP + 24} x2={BUILD_SLOT_X.T1 - inlineGap} y2={BUILD_YTOP + 24} stroke={BUILD_WIRE} strokeWidth="1.4" strokeDasharray="2 3" />
      <text x={BUILD_MAINS_X - 4} y={BUILD_YTOP - 10} fontSize="9" fontWeight="800" fill={C[700]}>230V AC</text>

      {/* top rail: T1 -> D1 -> C1 -> C2 -> IC1 -> C3 -> OUT -> bulb */}
      {seg(BUILD_SLOT_X.T1 + inlineGap, BUILD_SLOT_X.D1 - inlineGap)}
      {seg(BUILD_SLOT_X.D1 + inlineGap, BUILD_SLOT_X.C1)}
      {seg(BUILD_SLOT_X.C1, BUILD_SLOT_X.C2)}
      {seg(BUILD_SLOT_X.C2, BUILD_SLOT_X.IC1 - inlineGap)}
      {seg(BUILD_SLOT_X.IC1 + inlineGap, BUILD_SLOT_X.C3)}
      {seg(BUILD_SLOT_X.C3, BUILD_OUT_X)}
      {seg(BUILD_OUT_X, BUILD_BULB_X)}

      {/* segment labels */}
      <text x={(BUILD_SLOT_X.T1 + BUILD_SLOT_X.D1) / 2} y={BUILD_YTOP - 8} fontSize="8" fontWeight="700" fill={C[700]} textAnchor="middle">9V AC</text>
      <text x={(BUILD_SLOT_X.D1 + BUILD_SLOT_X.C1) / 2} y={BUILD_YTOP - 8} fontSize="8" fontWeight="700" fill={C[700]} textAnchor="middle">DC</text>
      <text x={(BUILD_SLOT_X.IC1 + BUILD_SLOT_X.C3) / 2} y={BUILD_YTOP - 8} fontSize="8" fontWeight="700" fill={C[700]} textAnchor="middle">5V</text>

      {/* bottom rail: from below T1 secondary to bulb, continuous */}
      <line x1={BUILD_SLOT_X.T1} y1={BUILD_YBOT} x2={BUILD_BULB_X} y2={BUILD_YBOT} stroke={railColor} strokeWidth={wireW} />
      <text x={BUILD_SLOT_X.T1 + 6} y={BUILD_YBOT + 14} fontSize="8" fontWeight="700" fill={C[700]}>common / 0V</text>

      {/* vertical stems */}
      <line x1={BUILD_SLOT_X.T1} y1={BUILD_YTOP + 16} x2={BUILD_SLOT_X.T1} y2={BUILD_YBOT} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_SLOT_X.D1} y1={BUILD_YTOP + 16} x2={BUILD_SLOT_X.D1} y2={BUILD_YBOT} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_SLOT_X.C1} y1={BUILD_YTOP} x2={BUILD_SLOT_X.C1} y2={midY - shuntGap} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_SLOT_X.C1} y1={midY + shuntGap} x2={BUILD_SLOT_X.C1} y2={BUILD_YBOT} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_SLOT_X.C2} y1={BUILD_YTOP} x2={BUILD_SLOT_X.C2} y2={midY - shuntGap} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_SLOT_X.C2} y1={midY + shuntGap} x2={BUILD_SLOT_X.C2} y2={BUILD_YBOT} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_SLOT_X.C3} y1={BUILD_YTOP} x2={BUILD_SLOT_X.C3} y2={midY - shuntGap} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_SLOT_X.C3} y1={midY + shuntGap} x2={BUILD_SLOT_X.C3} y2={BUILD_YBOT} stroke={railColor} strokeWidth={wireW} />
      <line x1={BUILD_SLOT_X.IC1} y1={BUILD_YTOP + 18} x2={BUILD_SLOT_X.IC1} y2={BUILD_YBOT} stroke={railColor} strokeWidth={wireW} />

      {/* output test points */}
      <circle cx={BUILD_OUT_X} cy={BUILD_YTOP} r="3" fill="none" stroke={railColor} strokeWidth="1.6" />
      <circle cx={BUILD_OUT_X} cy={BUILD_YBOT} r="3" fill="none" stroke={railColor} strokeWidth="1.6" />
      <text x={BUILD_OUT_X} y={BUILD_YTOP - 10} fontSize="9" fontWeight="800" fill={C[700]} textAnchor="middle">+5V</text>
      <text x={BUILD_OUT_X} y={BUILD_YBOT + 14} fontSize="8" fontWeight="700" fill={C[700]} textAnchor="middle">0V</text>

      {/* the 5V bulb load */}
      <BuildBulb x={BUILD_BULB_X} cy={midY} state={bulbState} />

      {/* slot boxes + glyphs */}
      {BUILD_SLOT_IDS.map((id) => {
        const chip = chipAt(id);
        const isPlaced = !!chip;
        const isWrong = tested && wrongSlots.includes(id);
        const cx = BUILD_SLOT_X[id];
        const inline = BUILD_SLOT_KIND[id] === "inline";
        const cy = inline ? BUILD_YTOP : midY;
        const w = inline ? 44 : 30, h = inline ? 30 : 40;
        return (
          <g key={id} transform={`translate(${cx},${cy})`}>
            <rect
              x={-w / 2} y={-h / 2} width={w} height={h} rx="8"
              fill={isWrong ? "#FFE3DA" : isPlaced ? C[50] : C[100]}
              stroke={isWrong ? BUILD_RED : isPlaced ? C[400] : C[300]}
              strokeWidth={isWrong || isPlaced ? 2 : 1.6}
              strokeDasharray={isPlaced ? "0" : "4 3"}
            />
            {isPlaced
              ? <BuildGlyph id={chip.glyph} stroke={isWrong ? BUILD_RED : C[900]} />
              : <text y="4" fontSize="14" fontWeight="800" fill={C[400]} textAnchor="middle">?</text>}
          </g>
        );
      })}
    </svg>
  );
}

function BuildScope({ ok }) {
  const w = 260, h = 56, mid = h / 2;
  let d = `M0 ${mid}`;
  if (ok) d += ` L${w} ${mid}`;
  else for (let x = 0; x <= w; x += 9) d += ` L${x} ${mid - 14 - Math.sin(x / 5) * 5}`;
  return (
    <svg viewBox={`0 0 ${w} ${h}`} width="100%" height={h} style={{ display: "block" }}>
      <rect width={w} height={h} rx="10" fill={C[950]} />
      {Array.from({ length: 6 }).map((_, i) => (
        <line key={i} x1={i * (w / 6)} y1="0" x2={i * (w / 6)} y2={h} stroke={C[900]} strokeWidth="1" />
      ))}
      <path d={d} fill="none" stroke={ok ? C[350] : "#FF6B4A"} strokeWidth="2.5" />
    </svg>
  );
}

function SchematicBuildScreen({ onBack }) {
  const [placed, setPlaced] = useState({});
  const [wrongId, setWrongId] = useState(null);
  const [drag, setDrag] = useState(null); // { id, x, y }
  const [powered, setPowered] = useState(false);
  const slotRefs = useRef({});
  const placedUids = new Set(Object.values(placed));
  const trayItems = BUILD_TRAY_ORDER.filter((uid) => !placedUids.has(uid));
  const allPlaced = Object.keys(placed).length === BUILD_SLOT_IDS.length;
  const wrongSlots = BUILD_SLOT_IDS.filter((id) => {
    if (!placed[id]) return false;
    const chip = BUILD_CHIP_POOL.find((c) => c.uid === placed[id]);
    return chip.slot !== id || !chip.correct;
  });
  const passing = powered && wrongSlots.length === 0;

  const startDrag = (id) => (e) => {
    e.preventDefault();
    setPowered(false);
    setDrag({ id, x: e.clientX, y: e.clientY });
  };
  const moveDrag = (e) => {
    if (!drag) return;
    setDrag((d) => ({ ...d, x: e.clientX, y: e.clientY }));
  };
  const endDrag = (e) => {
    if (!drag) return;
    const x = e.clientX, y = e.clientY;
    let hit = null;
    for (const id of BUILD_SLOT_IDS) {
      const el = slotRefs.current[id];
      if (!el) continue;
      const r = el.getBoundingClientRect();
      if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) { hit = id; break; }
    }
    const chip = BUILD_CHIP_POOL.find((c) => c.uid === drag.id);
    if (hit && chip && !placed[hit]) {
      setPlaced((prev) => ({ ...prev, [hit]: chip.uid }));
    } else if (hit) {
      setWrongId(hit);
      setTimeout(() => setWrongId(null), 500);
    }
    setDrag(null);
  };

  const reset = () => { setPlaced({}); setPowered(false); };

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", minHeight: 0 }} onPointerMove={moveDrag} onPointerUp={endDrag}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 24px 0" }}>
        <button onClick={onBack} style={{ width: 34, height: 34, borderRadius: "50%", border: "none", background: C[200], display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
          <ChevronLeft size={18} color={C[950]} />
        </button>
        <div>
          <div style={{ fontSize: 19, fontWeight: 800, color: C[950] }}>5V regulated supply (7805)</div>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "18px 24px 120px", display: "flex", flexDirection: "column" }}>
        <div style={{ position: "relative", background: C[100], border: `1.5px solid ${C[200]}`, borderRadius: 16, padding: "10px 8px" }}>
          <SupplySchematic placed={placed} wrongSlots={wrongSlots} tested={powered} passing={passing} />
          {/* invisible drop-target hitboxes, aligned to the SVG's own viewBox percentages */}
          <div style={{ position: "absolute", left: 8, right: 8, top: 10, bottom: 10, pointerEvents: "none" }}>
            {BUILD_SLOT_IDS.map((id) => {
              const cxPct = (BUILD_SLOT_X[id] / BUILD_VBW) * 100;
              const cyPct = ((BUILD_SLOT_KIND[id] === "inline" ? BUILD_YTOP : (BUILD_YTOP + BUILD_YBOT) / 2) / 210) * 100;
              return (
                <div
                  key={id}
                  ref={(el) => (slotRefs.current[id] = el)}
                  style={{
                    position: "absolute", left: `${cxPct}%`, top: `${cyPct}%`,
                    transform: "translate(-50%,-50%)", width: "13%", height: "22%",
                  }}
                />
              );
            })}
          </div>
        </div>

        <p style={{ fontSize: 11.5, color: C[700], lineHeight: 1.4, margin: "10px 2px" }}>
          Drag any part onto any blank - it'll click into place either way. Only the right part in the right spot survives power-on.
        </p>

        {/* tray */}
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, justifyContent: "center", background: C[200], borderRadius: 16, padding: "12px 10px", minHeight: 58 }}>
          {trayItems.length === 0 && (
            <span style={{ fontSize: 11, fontWeight: 700, color: C[800] }}>All parts placed ✓</span>
          )}
          {trayItems.map((id) => {
            const p = BUILD_CHIP_POOL.find((x) => x.uid === id);
            return (
              <div
                key={id}
                onPointerDown={startDrag(id)}
                style={{
                  display: "flex", alignItems: "center", gap: 6, background: C[50], borderRadius: 12,
                  padding: "6px 10px 6px 6px", boxShadow: "0 3px 8px rgba(115,56,16,0.15)",
                  cursor: "grab", touchAction: "none", userSelect: "none",
                }}
              >
                <svg width="30" height="30" viewBox="-20 -20 40 40"><BuildGlyph id={p.glyph} stroke={C[800]} /></svg>
                <div>
                  <div style={{ fontSize: 10.5, fontWeight: 800, color: C[950] }}>{p.name}</div>
                  <div style={{ fontSize: 9, color: C[700] }}>{p.spec}</div>
                </div>
              </div>
            );
          })}
        </div>

        <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
          <button onClick={reset} style={{ border: "none", borderRadius: 14, background: C[200], color: C[800], fontWeight: 800, fontSize: 13, padding: "12px 16px", display: "flex", alignItems: "center", gap: 6, cursor: "pointer" }}>
            <RotateCcw size={15} /> Reset
          </button>
          <button
            onClick={() => setPowered(true)}
            disabled={!allPlaced}
            style={{
              flex: 1, border: "none", borderRadius: 14, cursor: allPlaced ? "pointer" : "not-allowed",
              background: !allPlaced ? C[200] : powered ? C[950] : C[400],
              color: !allPlaced ? C[700] : C[50], fontWeight: 800, fontSize: 13,
              display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
            }}
          >
            <Power size={15} /> {allPlaced ? "Power on" : "Place all parts"}
          </button>
        </div>

        {powered && (
          <>
            <div style={{ marginTop: 12, borderRadius: 14, background: C[50], border: `1.5px solid ${C[200]}`, padding: 10 }}>
              <BuildScope ok={passing} />
            </div>
            <div style={{ marginTop: 10, display: "flex", gap: 8, alignItems: "flex-start", background: passing ? C[300] : "#FFE3DA", borderRadius: 14, padding: "10px 12px" }}>
              <CheckCircle2 size={18} color={passing ? C[950] : BUILD_RED} style={{ flexShrink: 0, marginTop: 1 }} />
              <div style={{ fontSize: 11.5, color: passing ? C[950] : BUILD_RED, fontWeight: 700 }}>
                {passing ? "Steady 5V DC at the output - bulb's lit." : "Wrong part feeding the wrong voltage - bulb just blew. Reset and check the highlighted slot."}
              </div>
            </div>
          </>
        )}
      </div>

      {/* floating dragged chip */}
      {drag && (() => {
        const p = BUILD_CHIP_POOL.find((x) => x.uid === drag.id);
        return (
          <div style={{
            position: "fixed", left: drag.x, top: drag.y, transform: "translate(-50%,-50%)",
            pointerEvents: "none", zIndex: 999, background: C[50], borderRadius: 12,
            padding: "6px 10px 6px 6px", boxShadow: "0 8px 20px rgba(0,0,0,0.25)",
            display: "flex", alignItems: "center", gap: 6,
          }}>
            <svg width="30" height="30" viewBox="-20 -20 40 40"><BuildGlyph id={p.glyph} stroke={C[800]} /></svg>
            <div style={{ fontSize: 10.5, fontWeight: 800, color: C[950] }}>{p.slot}</div>
          </div>
        );
      })()}
    </div>
  );
}

/* ---- LED CIRCUIT SIMULATOR - 3 parallel branches off one 5V rail,
   each with its own switch and resistor feeding its own LED. ---- */
const BUILD_V_SRC = 5, BUILD_VF = 2, BUILD_MIN_R = 0, BUILD_MAX_R = 2000;
const BUILD_R_CHIPS = [100, 220, 470, 1000];

function buildLedStatus(I_mA, on) {
  if (!on) return { tone: "off", text: "Switch open - this branch is off." };
  if (!isFinite(I_mA) || I_mA > 100) return { tone: "exploded", text: "Resistor too low - LED blown by the surge." };
  if (I_mA > 30) return { tone: "danger", text: `${I_mA.toFixed(0)} mA - too much for this LED, raise its resistor.` };
  if (I_mA < 5) return { tone: "dim", text: `Only ${I_mA.toFixed(1)} mA - too dim to see well.` };
  return { tone: "ok", text: `Lit - drawing ${I_mA.toFixed(1)} mA (safe range).` };
}

const BUILD_RES_DELTAS = [[0, 0], [8, 6], [-8, 14], [8, 22], [-8, 30], [8, 38], [0, 44]];
function buildResistorPath(x, y0) {
  return "M" + BUILD_RES_DELTAS.map(([dx, dy]) => `${x + dx},${y0 + dy}`).join(" L");
}

function BuildBranch({ x, topY, botY, on, I_mA, label }) {
  const swTop = topY + 10, swBot = topY + 40;
  const resTop = swBot + 6, resBot = resTop + 44;
  const ledTop = resBot + 6, ledBot = ledTop + 23;
  const ledMidY = (ledTop + ledBot) / 2;
  const exploded = on && (!isFinite(I_mA) || I_mA > 100);
  const brightness = on ? Math.min(1, Math.max(0, (I_mA - 5) / 25)) : 0;
  const ledFill = !on ? "none" : I_mA > 30 ? "#ff5540" : I_mA < 5 ? "rgba(255,70,50,0.25)" : `rgba(255,70,50,${(0.5 + brightness * 0.5).toFixed(2)})`;
  const glow = !on ? "none" : `drop-shadow(0 0 ${5 + brightness * 12}px rgba(255,70,50,${(0.4 + brightness * 0.5).toFixed(2)}))`;
  const rayOpacity = !on ? 0 : I_mA > 30 ? 1 : I_mA < 5 ? 0.15 : brightness;
  const wireColor = on ? C[400] : C[950];

  return (
    <g>
      <line x1={x} y1={topY} x2={x} y2={swTop} stroke={wireColor} strokeWidth="2" />
      <circle cx={x} cy={swTop} r="2.2" fill={C[950]} />
      {on
        ? <line x1={x} y1={swTop} x2={x} y2={swBot} stroke={C[400]} strokeWidth="2" />
        : <line x1={x} y1={swTop} x2={x + 15} y2={swTop + 16} stroke={C[950]} strokeWidth="2" />}
      <circle cx={x} cy={swBot} r="2.2" fill={C[950]} />
      <line x1={x} y1={swBot} x2={x} y2={resTop} stroke={wireColor} strokeWidth="2" />
      <path d={buildResistorPath(x, resTop)} fill="none" stroke={exploded ? BUILD_RED : C[950]} strokeWidth="2" />
      <line x1={x} y1={resBot} x2={x} y2={ledTop} stroke={wireColor} strokeWidth="2" />
      {exploded ? (
        <>
          <ellipse cx={x} cy={ledMidY} rx="16" ry="13" fill="#2a1c10" opacity="0.3" />
          <path d={`M${x - 14},${ledTop + 2} L${x - 5},${ledBot - 4} L${x},${ledTop + 10} L${x + 6},${ledBot - 2} L${x + 14},${ledTop + 2}`} fill="none" stroke={C[950]} strokeWidth="1.8" strokeLinejoin="round" />
          {[-50, -15, 20, 60, 110, 160, 200, 250].map((deg, i) => {
            const rad = (deg * Math.PI) / 180;
            return (
              <line key={i} x1={x + Math.cos(rad) * 12} y1={ledMidY + Math.sin(rad) * 12} x2={x + Math.cos(rad) * 26} y2={ledMidY + Math.sin(rad) * 26}
                stroke="#ff5540" strokeWidth="2" strokeLinecap="round" />
            );
          })}
        </>
      ) : (
        <>
          <polygon points={`${x - 14},${ledTop} ${x + 14},${ledTop} ${x},${ledBot}`} fill={ledFill} stroke={C[950]} strokeWidth="2" style={{ filter: glow, transition: "all .15s" }} />
          <line x1={x - 14} y1={ledBot} x2={x + 14} y2={ledBot} stroke={C[950]} strokeWidth="2" style={{ filter: on ? glow : "none" }} />
          {[[-6, -4], [-9, 3], [-6, 10]].map(([dx, dy], i) => (
            <line key={i} x1={x - 14} y1={ledTop + 8 + dy} x2={x - 24 + dx} y2={ledTop + 3 + dy} stroke="#ff5540" strokeWidth="2" style={{ opacity: rayOpacity, transition: "opacity .15s" }} />
          ))}
        </>
      )}
      <line x1={x} y1={ledBot} x2={x} y2={botY} stroke={wireColor} strokeWidth="2" />
      <text x={x} y={topY - 6} fontSize="9" fontWeight="800" fill={C[700]} textAnchor="middle">{label}</text>
    </g>
  );
}

function BuildParallelLedCircuit({ branches }) {
  const topY = 35, botY = 192, leftX = 22, rightX = 250;
  const xs = [95, 170, 245];
  return (
    <svg viewBox="0 0 270 225" width="100%" height="auto" style={{ display: "block" }}>
      <g stroke={C[950]} strokeWidth="2" fill="none">
        <line x1={leftX} y1={topY} x2={leftX + 6} y2={topY} />
        <line x1={leftX} y1={topY} x2={leftX} y2={topY + 40} strokeWidth="3" />
        <line x1={leftX - 8} y1={topY + 48} x2={leftX + 8} y2={topY + 48} strokeWidth="1.2" />
        <line x1={leftX - 8} y1={topY + 60} x2={leftX + 8} y2={topY + 60} strokeWidth="3" />
        <line x1={leftX - 5} y1={topY + 68} x2={leftX + 5} y2={topY + 68} strokeWidth="1.2" />
        <line x1={leftX} y1={topY + 68} x2={leftX} y2={botY} />
      </g>
      <text x={leftX - 16} y={topY + 30} fontSize="9" fontWeight="700" fill={C[700]}>+</text>
      <text x={leftX - 16} y={topY + 66} fontSize="9" fontWeight="700" fill={C[700]}>9V</text>

      <line x1={leftX} y1={topY} x2={rightX} y2={topY} stroke={C[950]} strokeWidth="2" />
      <line x1={leftX} y1={botY} x2={rightX} y2={botY} stroke={C[950]} strokeWidth="2" />
      <text x={rightX - 4} y={botY + 14} fontSize="8" fontWeight="700" fill={C[700]} textAnchor="end">0V</text>

      {branches.map((b, i) => (
        <BuildBranch key={i} x={xs[i]} topY={topY} botY={botY} on={b.on} I_mA={b.I_mA} label={`LED${i + 1}`} />
      ))}
    </svg>
  );
}

function LedSimScreen({ onBack }) {
  const [branches, setBranches] = useState([
    { r: 220, on: true },
    { r: 470, on: true },
    { r: 1000, on: false },
  ]);

  const withCurrent = branches.map((b) => ({ ...b, I_mA: b.on ? (b.r === 0 ? Infinity : ((BUILD_V_SRC - BUILD_VF) / b.r) * 1000) : 0 }));
  const totalMA = withCurrent.reduce((s, b) => s + b.I_mA, 0);

  const setR = (i, r) => setBranches((prev) => prev.map((b, idx) => (idx === i ? { ...b, r } : b)));
  const toggleOn = (i) => setBranches((prev) => prev.map((b, idx) => (idx === i ? { ...b, on: !b.on } : b)));

  return (
    <>
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 24px 0" }}>
        <button onClick={onBack} style={{ width: 34, height: 34, borderRadius: "50%", border: "none", background: C[200], display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
          <ChevronLeft size={18} color={C[950]} />
        </button>
        <div>
          <div style={{ fontSize: 19, fontWeight: 800, color: C[950] }}>3 parallel LEDs</div>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "18px 24px 120px", display: "flex", flexDirection: "column" }}>
        <div style={{ background: C[100], border: `1.5px solid ${C[200]}`, borderRadius: 16, padding: "10px 8px" }}>
          <BuildParallelLedCircuit branches={withCurrent} />
        </div>

        <p style={{ fontSize: 11.5, color: C[700], lineHeight: 1.4, margin: "10px 2px" }}>
          Each branch taps the same 5V rail independently - its own switch and resistor set that LED's current, with no effect on the other two. Drag a resistor to 0Ω and the LED will blow.
        </p>

        {withCurrent.map((b, i) => {
          const status = buildLedStatus(b.I_mA, b.on);
          const statusBg = { off: C[200], danger: "#FFE3DA", dim: C[100], ok: C[300], exploded: "#FFD2C2" }[status.tone];
          const statusColor = { off: C[800], danger: BUILD_RED, dim: C[800], ok: C[950], exploded: BUILD_RED }[status.tone];
          return (
            <div key={i} style={{ marginTop: 12, background: C[100], borderRadius: 16, padding: "12px 14px" }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <span style={{ fontSize: 12.5, fontWeight: 800, color: C[950] }}>LED{i + 1} branch</span>
                <button onClick={() => toggleOn(i)} style={{
                  width: 40, height: 23, borderRadius: 999, border: "none", cursor: "pointer", position: "relative",
                  background: b.on ? C[400] : C[300], transition: "background .15s", flexShrink: 0,
                }}>
                  <div style={{ position: "absolute", top: 2.5, left: b.on ? 19 : 2.5, width: 18, height: 18, borderRadius: "50%", background: C[50], transition: "left .15s", boxShadow: "0 1px 3px rgba(0,0,0,0.3)" }} />
                </button>
              </div>

              <div style={{ display: "flex", flexWrap: "wrap", gap: 5, margin: "8px 0 6px" }}>
                {BUILD_R_CHIPS.map((v) => (
                  <button key={v} onClick={() => setR(i, v)} style={{
                    border: "none", borderRadius: 999, padding: "4px 10px", fontSize: 10.5, fontWeight: 800, cursor: "pointer",
                    background: b.r === v ? C[400] : C[200], color: b.r === v ? C[50] : C[800],
                  }}>{v}Ω</button>
                ))}
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <input type="range" min={BUILD_MIN_R} max={BUILD_MAX_R} step="10" value={b.r} onChange={(e) => setR(i, parseInt(e.target.value, 10))} style={{ flex: 1, accentColor: C[400] }} />
                <span style={{ fontSize: 10.5, fontWeight: 800, color: C[950], minWidth: 46, textAlign: "right" }}>{b.r} Ω</span>
              </div>

              <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                <div style={{ flex: 1, fontSize: 10, fontWeight: 700, color: C[700] }}>Current: <span style={{ color: C[950] }}>{b.I_mA.toFixed(1)} mA</span></div>
              </div>
              <div style={{ marginTop: 6, fontSize: 10.5, fontWeight: 700, color: statusColor, background: statusBg, borderRadius: 10, padding: "6px 10px" }}>
                {status.text}
              </div>
            </div>
          );
        })}

        <div style={{ marginTop: 12, display: "flex", alignItems: "center", justifyContent: "space-between", background: C[300], borderRadius: 14, padding: "10px 14px" }}>
          <span style={{ fontSize: 12, fontWeight: 800, color: C[950] }}>Total drawn from battery</span>
          <span style={{ fontSize: 14, fontWeight: 800, color: C[950] }}>{totalMA.toFixed(1)} mA</span>
        </div>
      </div>
    </>
  );
}

/* ---- MODE SELECT - pick which activity to try ---- */
const BUILD_MODES = [
  { key: "schematic", label: "5V regulated supply", sub: "Drag real components onto a blanked schematic and power it on.", icon: Cpu },
  { key: "led", label: "3 parallel LEDs", sub: "Each branch gets its own switch and resistor off one 5V rail - tune all three live.", icon: Lightbulb },
];

function BuildModeSelectScreen({ onBack, onPick }) {
  return (
    <>
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 24px 0" }}>
        <button onClick={onBack} style={{ width: 34, height: 34, borderRadius: "50%", border: "none", background: C[200], display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
          <ChevronLeft size={18} color={C[950]} />
        </button>
        <div>
          <div style={{ fontSize: 19, fontWeight: 800, color: C[950] }}>Builds</div>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "18px 24px 120px", display: "flex", flexDirection: "column", gap: 14 }}>
        <p style={{ fontSize: 12.5, color: C[700], lineHeight: 1.5, margin: 0 }}>
          Two ways to learn the same components - build a real supply, or tune a live circuit.
        </p>

        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {BUILD_MODES.map((m) => {
            const Icon = m.icon;
            return (
              <button key={m.key} onClick={() => onPick(m.key)} style={{
                display: "flex", alignItems: "center", gap: 14, textAlign: "left", cursor: "pointer",
                border: `2px solid ${C[200]}`, background: C[50], borderRadius: 18, padding: "14px 16px",
              }}>
                <div style={{ width: 46, height: 46, borderRadius: 14, flexShrink: 0, background: C[200], display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <Icon size={22} color={C[800]} />
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 14, fontWeight: 800, color: C[950] }}>{m.label}</div>
                  <div style={{ fontSize: 12, color: C[700], marginTop: 2 }}>{m.sub}</div>
                </div>
                <ChevronRight size={18} color={C[700]} style={{ flexShrink: 0 }} />
              </button>
            );
          })}
        </div>
      </div>
    </>
  );
}

function BuildsScreen({ onBack }) {
  const [mode, setMode] = useState(null);
  if (mode === "schematic") return <SchematicBuildScreen onBack={() => setMode(null)} />;
  if (mode === "led") return <LedSimScreen onBack={() => setMode(null)} />;
  return <BuildModeSelectScreen onBack={onBack} onPick={setMode} />;
}

/* ============================================================
   APP SHELL
   ============================================================ */
export default function App() {
  const [tab, setTab] = useState("home");
  const [showProfile, setShowProfile] = useState(false);
  const [userName, setUserName] = useState("Jae Miguel");
  const [avatarId, setAvatarId] = useState(null);
  const avatarImg = AVATARS.find((a) => a.id === avatarId)?.img || null;

  let body;
  if (showProfile) {
    body = (
      <ProfileScreen
        userName={userName}
        setUserName={setUserName}
        avatarId={avatarId}
        setAvatarId={setAvatarId}
        onBack={() => setShowProfile(false)}
      />
    );
  } else if (tab === "roadmap") {
    body = <RoadmapScreen onBack={() => setTab("home")} />;
  } else if (tab === "logic") {
    body = <LogicGatesScreen onBack={() => setTab("home")} />;
  } else if (tab === "components") {
    body = <ComponentsBody onBack={() => setTab("home")} />;
  } else if (tab === "conversions") {
    body = <ConversionsBody onBack={() => setTab("home")} />;
  } else if (tab === "builds") {
    body = <BuildsScreen onBack={() => setTab("home")} />;
  } else {
    body = <HomeScreen tab={tab} setTab={setTab} userName={userName} avatarImg={avatarImg} onOpenProfile={() => setShowProfile(true)} />;
  }

  return (
    <div style={{ minHeight: "100vh", background: "#FFF3B0", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONT }}>
      <div
        style={{
          width: 380, height: 800,
          background: "#FEFBE8",
          borderRadius: 44,
          border: "1px solid #FFE988",
          boxShadow: "0 30px 70px rgba(150,110,10,0.22)",
          overflow: "hidden",
          position: "relative",
          display: "flex",
          flexDirection: "column",
        }}
      >
        {body}

        {!showProfile && <BottomNav tab={tab} setTab={setTab} />}
      </div>
    </div>
  );
}
